import type { H3Event } from 'h3'
import { getCfBindings } from './cf-env'
import { computeSha256 } from './plugin-signing'

// KVNamespace, WorkerLoader, WorkerLoaderWorkerCode, and WorkerStub below are global
// ambient types from server/types/worker-configuration.d.ts (generated by
// `pnpm run cf-typegen`) — no import needed. See server/types/cloudflare-bindings.d.ts
// for what's still hand-written.

// Code is stored under a key that carries its own SHA-256 (`plugin:{site}:{id}:server:{sum}`)
// — the same reasoning as theme CSS's versioned keys (cf-env.ts): an update writes a brand-new
// key that has only ever held one value, so KV's eventual consistency can never hand another
// colo the old code under the new row's checksum (which would fail the integrity check). The
// unversioned key is still read as a fallback for plugins installed before this.
function codeKey(siteId: string, pluginId: string, kind: 'server' | 'client', checksum?: string | null): string {
  return checksum ? `plugin:${siteId}:${pluginId}:${kind}:${checksum}` : `plugin:${siteId}:${pluginId}:${kind}`
}

async function getCode(event: H3Event, siteId: string, pluginId: string, kind: 'server' | 'client', checksum?: string | null): Promise<string | null> {
  const { kv } = getCfBindings(event)
  if (!kv) return null
  if (checksum) {
    const versioned = await kv.get(codeKey(siteId, pluginId, kind, checksum))
    if (versioned !== null) return versioned
  }
  return kv.get(codeKey(siteId, pluginId, kind))
}

async function putCode(event: H3Event, siteId: string, pluginId: string, kind: 'server' | 'client', code: string): Promise<void> {
  const { kv } = getCfBindings(event)
  if (!kv) throw createError({ statusCode: 503, message: 'Dynamic plugins require a Cloudflare KV namespace (PLUGIN_KV). Configure it in wrangler.toml.' })
  await kv.put(codeKey(siteId, pluginId, kind, await computeSha256(code)), code)
}

export function getPluginServerCode(event: H3Event, siteId: string, pluginId: string, checksum?: string | null): Promise<string | null> {
  return getCode(event, siteId, pluginId, 'server', checksum)
}

export function getPluginClientBundle(event: H3Event, siteId: string, pluginId: string, checksum?: string | null): Promise<string | null> {
  return getCode(event, siteId, pluginId, 'client', checksum)
}

export function putPluginServerCode(event: H3Event, siteId: string, pluginId: string, code: string): Promise<void> {
  return putCode(event, siteId, pluginId, 'server', code)
}

export function putPluginClientBundle(event: H3Event, siteId: string, pluginId: string, bundle: string): Promise<void> {
  return putCode(event, siteId, pluginId, 'client', bundle)
}

/**
 * Deletes a plugin's stored code — every version, or every version except the checksums in
 * `keep` (used after an update, once the row points at the new code).
 */
export async function deletePluginAssets(event: H3Event, siteId: string, pluginId: string, keep: (string | null | undefined)[] = []): Promise<void> {
  const { kv } = getCfBindings(event)
  if (!kv) return
  const keepKeys = new Set<string>()
  for (const sum of keep) {
    if (!sum) continue
    keepKeys.add(codeKey(siteId, pluginId, 'server', sum))
    keepKeys.add(codeKey(siteId, pluginId, 'client', sum))
  }
  const prefix = `plugin:${siteId}:${pluginId}:`
  let cursor: string | undefined
  do {
    const page = await kv.list({ prefix, cursor })
    await Promise.all(page.keys.filter(k => !keepKeys.has(k.name)).map(k => kv.delete(k.name)))
    cursor = page.list_complete ? undefined : page.cursor
  } while (cursor)
}

// A plugin is third-party code: Ed25519-signature-verified and checksum-matched at
// install/request time (see assertCodeIntegrity() call sites), which proves *authorship
// consistency*, not that the code is benign or bug-free. Without an explicit `limits`, a
// dynamic Worker runs under the parent request's own plan-standard CPU/subrequest budget —
// a runaway loop in plugin code would burn CPU time against (and could starve) the request
// that spawned it. `cpuMs: 50` bounds the plugin's *own* computation; time spent waiting on
// a capability call (storage, content, AI — host-side, see plugin-host/entrypoints.ts) or on
// an allowlisted fetch isn't CPU time. `subRequests: 50` caps how many of those calls (each
// capability RPC and each outbound fetch counts) a single invocation can make.
// Set on *both* the WorkerLoaderWorkerCode (below) and every getEntrypoint() call (see
// plugin-runtime.ts) — per Cloudflare's docs the lower of the two wins.
// See https://developers.cloudflare.com/dynamic-workers/usage/limits/ and
// https://developers.cloudflare.com/dynamic-workers/usage/egress-control/.
export const PLUGIN_WORKER_LIMITS: { cpuMs: number, subRequests: number } = {
  cpuMs: 50,
  subRequests: 50,
}

export interface PluginWorkerBindings {
  /** Bindings the plugin sees as its `env` — only host-made capability stubs, never raw D1/KV/R2. */
  env?: Record<string, unknown>
  /**
   * Where the plugin's fetch()/connect() go: `null` blocks the network entirely, otherwise
   * a host gateway that only lets allowlisted hosts through (PluginEgressGateway).
   */
  globalOutbound?: unknown
}

export function spawnPluginWorker(
  event: H3Event,
  cacheId: string,
  getCode: () => Promise<string>,
  bindings: PluginWorkerBindings = {},
): WorkerStub {
  const { loader } = getCfBindings(event)
  if (!loader) throw createError({ statusCode: 503, message: 'Dynamic Workers (LOADER binding) are not available in this environment.' })

  return loader.get(cacheId, async (): Promise<WorkerLoaderWorkerCode> => {
    const code = await getCode()
    return {
      compatibilityDate: '2026-04-01',
      mainModule: 'index.js',
      modules: { 'index.js': code },
      ...(bindings.env ? { env: bindings.env } : {}),
      globalOutbound: (bindings.globalOutbound ?? null) as WorkerLoaderWorkerCode['globalOutbound'],
      limits: PLUGIN_WORKER_LIMITS,
    }
  })
}
